-- Phase 2 transactional lifecycle engine; service_role-only RPCs.
-- Copy to file generated by: supabase migration new focus_v2_lifecycle_rpc
-- Call from a trusted server only, after validating session identity.
begin;

create function public.focus_v2_create_session(
  p_user_id uuid,
  p_task_id uuid,
  p_focus_minutes integer,
  p_short_break_minutes integer,
  p_long_break_minutes integer,
  p_round_count integer,
  p_long_break_every integer,
  p_auto_start_breaks boolean,
  p_auto_start_focus boolean
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid;
  v_round integer;
  v_is_long boolean;
  v_now timestamptz := clock_timestamp();
begin
  if p_user_id is null or not exists (
    select 1 from public.profiles where id=p_user_id
  ) then
    raise exception using errcode='22023', message='Invalid focus user';
  end if;
  if p_task_id is not null and not exists (
    select 1 from public.tasks where id=p_task_id and user_id=p_user_id
  ) then
    raise exception using errcode='22023', message='Task does not belong to focus user';
  end if;
  if p_focus_minutes is null or p_focus_minutes not between 5 and 120
     or p_short_break_minutes is null or p_short_break_minutes not between 1 and 30
     or p_long_break_minutes is null or p_long_break_minutes not between 5 and 60
     or p_round_count is null or p_round_count not between 1 and 8
     or p_long_break_every is null or p_long_break_every not between 2 and 8
     or p_auto_start_breaks is null or p_auto_start_focus is null then
    raise exception using errcode='22023', message='Invalid Pomodoro configuration';
  end if;

  insert into public.focus_sessions (
    user_id, task_id, session_mode, planned_minutes, actual_focus_minutes,
    started_at, status
  ) values (
    p_user_id, p_task_id, 'pomodoro', p_focus_minutes*p_round_count, 0,
    v_now, 'ongoing'
  ) returning id into v_id;

  insert into public.focus_session_plans (
    session_id, focus_minutes, short_break_minutes, long_break_minutes,
    round_count, long_break_every, auto_start_breaks, auto_start_focus
  ) values (
    v_id, p_focus_minutes, p_short_break_minutes, p_long_break_minutes,
    p_round_count, p_long_break_every, p_auto_start_breaks, p_auto_start_focus
  );

  for v_round in 1..p_round_count loop
    insert into public.focus_session_segments (
      session_id, position, round_number, segment_kind, planned_seconds,
      status, started_at
    ) values (
      v_id, 2*v_round-1, v_round, 'focus', p_focus_minutes*60,
      case when v_round=1 then 'running' else 'pending' end,
      case when v_round=1 then v_now else null end
    );
    if v_round < p_round_count then
      v_is_long := mod(v_round,p_long_break_every)=0;
      insert into public.focus_session_segments (
        session_id, position, round_number, segment_kind, planned_seconds
      ) values (
        v_id, 2*v_round, v_round,
        case when v_is_long then 'long_break' else 'short_break' end,
        (case when v_is_long then p_long_break_minutes else p_short_break_minutes end)*60
      );
    end if;
  end loop;
  return v_id;
end;
$$;

create function public.focus_v2_transition(
  p_user_id uuid,
  p_session_id uuid,
  p_action text,
  p_expected_segment_id uuid default null
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_parent public.focus_sessions%rowtype;
  v_plan public.focus_session_plans%rowtype;
  v_seg public.focus_session_segments%rowtype;
  v_next public.focus_session_segments%rowtype;
  v_now timestamptz := clock_timestamp();
  v_pause integer := 0;
  v_elapsed integer := 0;
  v_focus_seconds bigint := 0;
  v_auto_start boolean;
  v_target uuid;
begin
  if p_user_id is null or p_session_id is null or p_action is null
    or p_action not in ('pause','resume','complete','skip_break','start_next','cancel') then
    raise exception using errcode='22023', message='Invalid Focus V2 transition';
  end if;
  -- All calls serialize on the same parent. Cross-user ids reveal no data.
  select * into v_parent from public.focus_sessions
   where id=p_session_id and user_id=p_user_id and session_mode='pomodoro'
   for update;
  if not found or v_parent.status not in ('ongoing','paused') then
    raise exception using errcode='P0001', message='Focus session state changed';
  end if;
  select * into v_plan from public.focus_session_plans where session_id=p_session_id;
  if not found then
    raise exception using errcode='P0001', message='Missing Pomodoro plan';
  end if;

  if p_action='start_next' then
    if v_parent.status <> 'ongoing' or p_expected_segment_id is null
       or exists (select 1 from public.focus_session_segments
                  where session_id=p_session_id and status in ('running','paused')) then
      raise exception using errcode='P0001', message='Focus segment state changed';
    end if;
    select * into v_seg from public.focus_session_segments
      where session_id=p_session_id and status='pending'
      order by position limit 1 for update;
    if not found or v_seg.id <> p_expected_segment_id
      or exists (select 1 from public.focus_session_segments
                 where session_id=p_session_id and position<v_seg.position
                   and status not in ('completed','skipped')) then
      raise exception using errcode='P0001', message='Focus segment state changed';
    end if;
    update public.focus_session_segments set status='running', started_at=v_now
      where id=v_seg.id;
    return jsonb_build_object('parentStatus','ongoing','segmentId',v_seg.id,
      'nextSegmentId',null,'parentCompleted',false);
  end if;

  select * into v_seg from public.focus_session_segments
    where session_id=p_session_id and status in ('running','paused')
    limit 1 for update;

  if p_action='cancel' then
    if found then
      if p_expected_segment_id is not null and v_seg.id <> p_expected_segment_id then
        raise exception using errcode='P0001', message='Focus segment state changed';
      end if;
      v_elapsed := least(v_seg.planned_seconds, greatest(0,
        floor(extract(epoch from (
          (case when v_seg.status='paused' then v_seg.paused_at else v_now end)
          - v_seg.started_at
        )))::integer - v_seg.total_paused_seconds));
      update public.focus_session_segments set status='interrupted',
        paused_at=null, ended_at=v_now, actual_seconds=v_elapsed
        where id=v_seg.id;
    end if;
    select coalesce(sum(actual_seconds),0) into v_focus_seconds
      from public.focus_session_segments
      where session_id=p_session_id and segment_kind='focus'
        and status in ('completed','interrupted');
    v_pause := case when v_parent.status='paused' and v_parent.paused_at is not null
      then greatest(0, floor(extract(epoch from v_now-v_parent.paused_at))::integer)
      else 0 end;
    update public.focus_sessions set status='cancelled', ended_at=v_now,
      paused_at=null, total_paused_seconds=total_paused_seconds+v_pause,
      actual_focus_minutes=least(planned_minutes, floor(v_focus_seconds::numeric/60)::integer)
      where id=p_session_id;
    return jsonb_build_object('parentStatus','cancelled','segmentId',v_seg.id,
      'nextSegmentId',null,'parentCompleted',false);
  end if;

  if p_expected_segment_id is null or not found or v_seg.id <> p_expected_segment_id then
    raise exception using errcode='P0001', message='Focus segment state changed';
  end if;

  if p_action='pause' then
    if v_parent.status <> 'ongoing' or v_seg.status <> 'running' then
      raise exception using errcode='P0001', message='Focus segment state changed';
    end if;
    update public.focus_session_segments set status='paused', paused_at=v_now where id=v_seg.id;
    update public.focus_sessions set status='paused', paused_at=v_now where id=p_session_id;
    return jsonb_build_object('parentStatus','paused','segmentId',v_seg.id,
      'nextSegmentId',null,'parentCompleted',false);
  end if;

  if p_action='resume' then
    if v_parent.status <> 'paused' or v_seg.status <> 'paused' or v_seg.paused_at is null then
      raise exception using errcode='P0001', message='Focus segment state changed';
    end if;
    v_pause := greatest(0, floor(extract(epoch from v_now-v_seg.paused_at))::integer);
    update public.focus_session_segments set status='running', paused_at=null,
      total_paused_seconds=total_paused_seconds+v_pause where id=v_seg.id;
    update public.focus_sessions set status='ongoing', paused_at=null,
      total_paused_seconds=total_paused_seconds+v_pause where id=p_session_id;
    return jsonb_build_object('parentStatus','ongoing','segmentId',v_seg.id,
      'nextSegmentId',null,'parentCompleted',false);
  end if;

  if v_parent.status <> 'ongoing' or v_seg.status <> 'running' then
    raise exception using errcode='P0001', message='Focus segment state changed';
  end if;
  if p_action='skip_break' and v_seg.segment_kind='focus' then
    raise exception using errcode='22023', message='A focus round cannot be skipped';
  end if;
  v_elapsed := least(v_seg.planned_seconds, greatest(0,
    floor(extract(epoch from (v_now-v_seg.started_at)))::integer
      - v_seg.total_paused_seconds));
  if p_action='complete' and v_elapsed < v_seg.planned_seconds then
    raise exception using errcode='P0001', message='Focus segment has not reached its planned duration';
  end if;

  update public.focus_session_segments set
    status=case when p_action='complete' then 'completed' else 'skipped' end,
    ended_at=v_now, actual_seconds=v_elapsed
    where id=v_seg.id;

  select * into v_next from public.focus_session_segments
    where session_id=p_session_id and position>v_seg.position
    order by position limit 1 for update;

  if not found then
    select coalesce(sum(actual_seconds),0) into v_focus_seconds
      from public.focus_session_segments
      where session_id=p_session_id and segment_kind='focus' and status='completed';
    update public.focus_sessions set status='completed', ended_at=v_now,
      paused_at=null,
      actual_focus_minutes=least(planned_minutes, floor(v_focus_seconds::numeric/60)::integer)
      where id=p_session_id;
    return jsonb_build_object('parentStatus','completed','segmentId',v_seg.id,
      'nextSegmentId',null,'parentCompleted',true);
  end if;

  if v_next.status <> 'pending' then
    raise exception using errcode='P0001', message='Unexpected next segment state';
  end if;
  v_auto_start := case when v_next.segment_kind='focus'
    then v_plan.auto_start_focus else v_plan.auto_start_breaks end;
  if v_auto_start then
    update public.focus_session_segments set status='running', started_at=v_now
      where id=v_next.id;
  end if;
  return jsonb_build_object('parentStatus','ongoing','segmentId',v_seg.id,
    'nextSegmentId',v_next.id,'parentCompleted',false,
    'nextStarted',v_auto_start);
end;
$$;

-- Functions are in an exposed schema, so permissions must be extremely tight.
-- Both use SECURITY INVOKER, run with service_role privileges, and explicitly
-- filter the provided user ID; callers MUST validate that ID against auth.getUser().
revoke all on function public.focus_v2_create_session(uuid,uuid,integer,integer,integer,integer,integer,boolean,boolean)
  from public, anon, authenticated;
revoke all on function public.focus_v2_transition(uuid,uuid,text,uuid)
  from public, anon, authenticated;
grant execute on function public.focus_v2_create_session(uuid,uuid,integer,integer,integer,integer,integer,boolean,boolean)
  to service_role;
grant execute on function public.focus_v2_transition(uuid,uuid,text,uuid)
  to service_role;
commit;
